body.query:
query($address:String!, $chainId:Int!){vaultByAddress(address:$address,chainId:$chainId){
  address name symbol
  asset { symbol address decimals price { usd timestamp } }
  chain { id network }
  state {
    timestamp blockNumber totalAssets totalAssetsUsd apy netApy fee
    allocation {
      supplyAssets supplyAssetsUsd supplyCapUsd
      market {
        marketId lltv
        loanAsset { symbol address decimals price { usd timestamp } }
        collateralAsset { symbol address decimals price { usd timestamp } }
        oracle { address }
        state { timestamp blockNumber supplyAssets borrowAssets liquidityAssets collateralAssets supplyApy borrowApy utilization supplyAssetsUsd borrowAssetsUsd liquidityAssetsUsd collateralAssetsUsd }
      }
    }
  }
}}

